<?php
require_once __DIR__ . '/../app/layout.php';$u=require_role(['volunteer','admin']);$pdo=db();$errors=[];
function route_distance_km(float $a,float $b,float $c,float $d):float{$r=6371.0;$p1=deg2rad($a);$p2=deg2rad($c);$dp=deg2rad($c-$a);$dl=deg2rad($d-$b);$x=sin($dp/2)**2+cos($p1)*cos($p2)*sin($dl/2)**2;return 2*$r*asin(min(1,sqrt($x)));}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();try{$action=$_POST['action']??'';
  if($action==='create'){$volunteerId=$u['role']==='admin'?(int)($_POST['volunteer_id']??0):(int)$u['id'];$startLat=filter_var($_POST['start_lat']??null,FILTER_VALIDATE_FLOAT);$startLng=filter_var($_POST['start_lng']??null,FILTER_VALIDATE_FLOAT);$ids=array_values(array_unique(array_filter(array_map('intval',$_POST['delivery_ids']??[]))));if($volunteerId<1||$startLat===false||$startLng===false||$startLat===null||$startLng===null||$startLat < -90||$startLat>90||$startLng < -180||$startLng>180)throw new RuntimeException('Choose a volunteer and enter valid starting coordinates.');if(count($ids)<2||count($ids)>15)throw new RuntimeException('Select between 2 and 15 deliveries with recorded GPS coordinates.');$placeholders=implode(',',array_fill(0,count($ids),'?'));$args=$ids;$args[]=$volunteerId;$sql="SELECT d.id,d.status,d.gps_lat AS lat,d.gps_lng AS lng,sf.food_name,rec.name AS recipient FROM deliveries d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users rec ON rec.id=dr.requested_by WHERE d.id IN ($placeholders) AND d.volunteer_id=? AND d.status IN ('scheduled','picked_up','in_transit') AND d.gps_lat IS NOT NULL AND d.gps_lng IS NOT NULL";$q=$pdo->prepare($sql);$q->execute($args);$stops=$q->fetchAll();if(count($stops)!==count($ids))throw new RuntimeException('Every selected delivery must be assigned, active and have GPS coordinates.');$remaining=$stops;$ordered=[];$lat=(float)$startLat;$lng=(float)$startLng;$distance=0;while($remaining){$bestIndex=0;$bestDistance=INF;foreach($remaining as $i=>$stop){$d=route_distance_km($lat,$lng,(float)$stop['lat'],(float)$stop['lng']);if($d<$bestDistance){$bestDistance=$d;$bestIndex=$i;}}$chosen=$remaining[$bestIndex];$chosen['_leg']=$bestDistance;$distance+=$bestDistance;$ordered[]=$chosen;$lat=(float)$chosen['lat'];$lng=(float)$chosen['lng'];array_splice($remaining,$bestIndex,1);}$pdo->beginTransaction();$pdo->prepare("INSERT INTO route_plans(volunteer_id,status,planned_distance_km) VALUES(?,'proposed',?)")->execute([$volunteerId,$distance]);$routeId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO route_stops(route_id,delivery_id,sequence_no,latitude,longitude) VALUES(?,?,?,?,?)');foreach($ordered as $i=>$s)$ins->execute([$routeId,$s['id'],$i+1,$s['lat'],$s['lng']]);$pdo->commit();audit((int)$u['id'],'route_plan_created','route_plans',$routeId,'stops='.count($ordered));flash('Route proposal created. This is a straight-line nearest-neighbour estimate, not traffic-aware navigation.');redirect('route_planner.php?route='.$routeId);
  }elseif($action==='status'){$routeId=(int)($_POST['route_id']??0);$status=$_POST['status']??'';if(!in_array($status,['accepted','in_progress','completed','cancelled'],true))throw new RuntimeException('Invalid route status.');$q=$pdo->prepare('SELECT * FROM route_plans WHERE id=?'.($u['role']==='admin'?'':' AND volunteer_id=?'));$q->execute($u['role']==='admin'?[$routeId]:[$routeId,$u['id']]);if(!$q->fetch())throw new RuntimeException('Route not found or access denied.');$pdo->prepare('UPDATE route_plans SET status=? WHERE id=?')->execute([$status,$routeId]);audit((int)$u['id'],'route_status_changed','route_plans',$routeId,$status);flash('Route status updated.');redirect('route_planner.php?route='.$routeId);}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not create or update route. Verify migration and delivery GPS data.';}}
$volunteers=$pdo->query("SELECT id,name FROM users WHERE role='volunteer' AND is_active=1 AND verification_status='verified' ORDER BY name")->fetchAll();$args=[];$sql="SELECT d.id,d.status,d.gps_lat,d.gps_lng,sf.food_name,rec.name AS recipient FROM deliveries d JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users rec ON rec.id=dr.requested_by WHERE d.status IN ('scheduled','picked_up','in_transit') AND d.gps_lat IS NOT NULL AND d.gps_lng IS NOT NULL AND d.volunteer_id IS NOT NULL";if($u['role']!=='admin'){$sql.=' AND d.volunteer_id=?';$args[]=$u['id'];}$sql.=' ORDER BY d.updated_at DESC LIMIT 100';$q=$pdo->prepare($sql);$q->execute($args);$eligible=$q->fetchAll();$routeId=(int)($_GET['route']??0);$route=null;$routeStops=[];if($routeId){$q=$pdo->prepare('SELECT r.*,u.name AS volunteer_name FROM route_plans r JOIN users u ON u.id=r.volunteer_id WHERE r.id=?'.($u['role']==='admin'?'':' AND r.volunteer_id=?'));$q->execute($u['role']==='admin'?[$routeId]:[$routeId,$u['id']]);$route=$q->fetch();if($route){$q=$pdo->prepare('SELECT rs.*,d.status AS delivery_status,sf.food_name,rec.name AS recipient FROM route_stops rs JOIN deliveries d ON d.id=rs.delivery_id JOIN donation_requests dr ON dr.id=d.donation_request_id JOIN surplus_food sf ON sf.id=dr.surplus_food_id JOIN users rec ON rec.id=dr.requested_by WHERE rs.route_id=? ORDER BY rs.sequence_no');$q->execute([$routeId]);$routeStops=$q->fetchAll();}}
page_header('Route planner');?>
<div class="page-intro"><div class="eyebrow">VOLUNTEER LOGISTICS</div><h1>Route <em>planner.</em></h1><p>Build a suggested order for active deliveries with recorded GPS coordinates. The route planner does not replace delivery status tracking or provide live traffic routing.</p></div><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?>
<div class="form-panel"><h2>Create route proposal</h2><?php if(!$eligible):?><p class="muted">No active assigned deliveries with GPS coordinates are available. Deliveries need coordinates before they can be included.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><?php if($u['role']==='admin'):?><label class="full">Volunteer<select name="volunteer_id" required><option value="">Select verified volunteer</option><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><?php endif;?><label>Start latitude<input type="number" name="start_lat" min="-90" max="90" step="any" required placeholder="23.8103"></label><label>Start longitude<input type="number" name="start_lng" min="-180" max="180" step="any" required placeholder="90.4125"></label><fieldset class="full"><legend>Select 2–15 deliveries</legend><?php foreach($eligible as $d):?><label class="check-row"><input type="checkbox" name="delivery_ids[]" value="<?=(int)$d['id']?>"> Delivery #<?=(int)$d['id']?> · <?=e($d['food_name'])?> → <?=e($d['recipient'])?> (<?=e($d['gps_lat'])?>, <?=e($d['gps_lng'])?>)</label><?php endforeach;?></fieldset><div class="full"><button class="btn" type="submit">Optimize stop order</button></div></form><?php endif;?></div>
<?php if($route):?><div class="section-heading"><div><div class="eyebrow">ROUTE #<?=(int)$route['id']?></div><h2>Suggested route · <?=e($route['volunteer_name'])?></h2><p><?=number_format((float)$route['planned_distance_km'],2)?> km estimated straight-line leg total · <?=e($route['status'])?></p></div></div><div id="route-map" style="height:380px;border-radius:16px;border:1px solid #dce6de"></div><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const routeStops=<?=json_encode(array_map(fn($s)=>['lat'=>(float)$s['latitude'],'lng'=>(float)$s['longitude'],'label'=>'Stop '.$s['sequence_no'].' · Delivery #'.$s['delivery_id'].' · '.$s['food_name']],$routeStops),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;if(window.L&&routeStops.length){const map=L.map('route-map').setView([routeStops[0].lat,routeStops[0].lng],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);const pts=[];routeStops.forEach(s=>{const p=[s.lat,s.lng];pts.push(p);L.marker(p).addTo(map).bindPopup(s.label)});L.polyline(pts).addTo(map);map.fitBounds(pts,{padding:[20,20]});}</script><div class="table-wrap"><table><thead><tr><th>Order</th><th>Delivery</th><th>Food</th><th>Recipient</th><th>Coordinates</th><th>Status</th></tr></thead><tbody><?php foreach($routeStops as $s):?><tr><td><?=(int)$s['sequence_no']?></td><td>#<?=(int)$s['delivery_id']?></td><td><?=e($s['food_name'])?></td><td><?=e($s['recipient'])?></td><td><?=e($s['latitude'])?>, <?=e($s['longitude'])?></td><td><?=e($s['delivery_status'])?></td></tr><?php endforeach;?></tbody></table></div><form method="post" class="form-panel form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="route_id" value="<?=(int)$route['id']?>"><label>Route status<select name="status"><option value="accepted">Accepted</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><div><button class="btn" type="submit">Update route</button></div></form><?php elseif($routeId):?><div class="alert error">Route not found or you do not have access.</div><?php endif;?>
<div class="section-heading"><div><div class="eyebrow">SAVED ROUTES</div><h2>Recent route plans</h2></div></div><?php $q=$pdo->prepare('SELECT r.*,u.name AS volunteer_name,(SELECT COUNT(*) FROM route_stops s WHERE s.route_id=r.id) AS stop_count FROM route_plans r JOIN users u ON u.id=r.volunteer_id'.($u['role']==='admin'?'':' WHERE r.volunteer_id=?').' ORDER BY r.created_at DESC LIMIT 30');$q->execute($u['role']==='admin'?[]:[$u['id']]);$routes=$q->fetchAll();?><div class="table-wrap"><table><thead><tr><th>Route</th><th>Volunteer</th><th>Stops</th><th>Distance estimate</th><th>Status</th><th>Created</th><th>View</th></tr></thead><tbody><?php foreach($routes as $r):?><tr><td>#<?=(int)$r['id']?></td><td><?=e($r['volunteer_name'])?></td><td><?=(int)$r['stop_count']?></td><td><?=number_format((float)$r['planned_distance_km'],2)?> km</td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><a href="<?=e(url('route_planner.php?route='.(int)$r['id']))?>">Open route</a></td></tr><?php endforeach;?><?php if(!$routes):?><tr><td colspan="7" class="table-empty">No route plans yet.</td></tr><?php endif;?></tbody></table></div><?php page_footer();?>
